def convert_units(distance, from_unit, to_unit):
    """
    Converts a given distance from one unit to another.

    :param distance: The distance to convert.
    :param from_unit: The unit of measurement from which to convert (e.g. 'km', 'm', 'in', 'ft', 'yd', 'mi').
    :param to_unit: The unit of measurement to convert to (e.g. 'km', 'm', 'in', 'ft', 'yd', 'mi').
    :return: The converted distance.
    """

    # Define conversion factors for common units
    km_to_m = 1000
    m_to_km = 0.001
    mi_to_km = 1.60934
    km_to_mi = 0.621371

    # Calculate conversion factor based on the units
    if from_unit == 'km':
        conversion_factor = km_to_m
    elif from_unit == 'm':
        conversion_factor = 1
    elif from_unit == 'in':
        conversion_factor = 2.54
    elif from_unit == 'ft':
        conversion_factor = 3.28
    elif from_unit == 'yd':
        conversion_factor = 91.44
    elif from_unit == 'mi':
        conversion_factor = mi_to_km
    else:
        raise ValueError(f"Invalid unit '{from_unit}'. Supported units are 'km', 'm', 'in', 'ft', 'yd', 'mi'.")

    if to_unit == 'km':
        conversion_factor_to = km_to_m
    elif to_unit == 'm':
        conversion_factor_to = 1
    elif to_unit == 'in':
        conversion_factor_to = 2.54
    elif to_unit == 'ft':
        conversion_factor_to = 3.28
    elif to_unit == 'yd':
        conversion_factor_to = 91.44
    elif to_unit == 'mi':
        conversion_factor_to = mi_to_km
    else:
        raise ValueError(f"Invalid unit '{to_unit}'. Supported units are 'km', 'm', 'in', 'ft', 'yd', 'mi'.")

    # Convert distance and format output
    return format(distance * conversion_factor, '.3f') * conversion_factor_to


# Example usage
print(convert_units(10, 'km', 'mi'))  # Output: 6.21
```

